parameters.jsCode:
const results = $input.all();
const contact = results.find(item => item.json.id);
return [{
  json: {
    foundVid: contact ? contact.json.id : null
  }
}];

const profile = $('Execute a SQL query').first().json.profile || {};
const userText = $('Telegram Trigger').first().json.message.text?.trim() || "";
const pendingField = profile.onboarding_pending_field || null;
const isFirstMessage = !pendingField && !profile.name;

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/_/g, ' ')
    .replace(/\*/g, ' ')
    .replace(/`/g, "'");
}

// NEU: Validierung fuer den HubSpot Private-App-Token-Paste. Bei ungueltigem
// Format NICHT als beantwortet werten, sondern nochmal nachfragen -- sonst
// wuerde ein aus Versehen falsch eingefuegter Text (z.B. die HubSpot-URL
// statt des Tokens) stillschweigend als "kein Token" durchgehen.
if (!isFirstMessage && pendingField === 'hubspot_token') {
  const looksValid = /^pat-/.test(userText.trim());
  if (!looksValid) {
    return [{ json: {
      updates: {},
      nextPendingField: 'hubspot_token',
      onboardingComplete: false,
      reply: escapeHtml('Das sieht nicht nach einem gueltigen HubSpot Private-App-Token aus (muss mit "pat-" beginnen). Bitte nochmal aus HubSpot kopieren und schicken.'),
      outlookAuthUrl: '',
      hubspotSetupUrl: '',
      hubspotToken: ''
    } }];
  }
}

const FIELDS = [
  { key: 'name', mandatory: true, question: 'Wie heißt du bzw. wie soll ich dich ansprechen?' },
  { key: 'anrede', mandatory: true, question: 'Darf ich dich duzen, oder bevorzugst du "Sie"?' },
  { key: 'tonalitaet', mandatory: true, question: 'Soll mein Tonfall eher förmlich-professionell oder locker-kollegial sein? (foermlich/locker)' },
  { key: 'hat_outlook', mandatory: true, question: 'Nutzt du Outlook für Kalender und Email? (ja/nein)' },
  { key: 'hat_hubspot', mandatory: true, question: 'Nutzt du HubSpot als CRM? (ja/nein)' },
  { key: 'hubspot_token', mandatory: true, question: 'Bitte erstelle ein HubSpot Private App und schick mir den Token (beginnt mit "pat-") -- Anleitung kommt gleich als separate Nachricht.' },
  { key: 'arbeitszeiten', mandatory: false, question: 'Was sind deine üblichen Arbeitszeiten? (Standard: Mo–Fr 9–17 Uhr — einfach "Standard" antworten)' },
  { key: 'prioritaeten', mandatory: false, question: 'Gibt es aktuelle Prioritäten, die ich im Hinterkopf behalten soll? (optional — "nein" zum Überspringen)' },
  { key: 'business_context', mandatory: false, question: 'Was ist dein Business bzw. deine Tätigkeit? (kurz, 1-2 Sätze — hilft Jonas z.B. bei Kontakt-/Lead-Bewertungen aus Screenshots)' },
  { key: 'briefing_uhrzeit', mandatory: false, question: 'Um wie viel Uhr soll dein Morgen-Briefing kommen? (Standard: 07:30 — "Standard" antworten zum Uebernehmen)' },
  { key: 'briefing_inhalt', mandatory: false, question: 'Was soll das Briefing zeigen: nur Kalender, Kalender und Mails, oder alles inkl. HubSpot? (kalender / kalender-mails / alles — Standard: alles)' },
  { key: 'company_domain', mandatory: false, question: 'Was ist deine Firmen-Domain? (z.B. beispiel-firma.de — hilft mir externe Meeting-Teilnehmer zu erkennen, optional — "skip" zum Ueberspringen)' },
  { key: 'abend_recap_uhrzeit', mandatory: false, question: 'Falls du das Abend-Recap nutzen willst: um wie viel Uhr soll ich fragen wie dein Tag war? (Standard: 19:00 — "Standard" antworten, das Feature bleibt trotzdem erstmal aus bis du es aktivierst)' },
];
function extractValue(field, raw) {
  const t = raw.toLowerCase().trim();
  switch (field) {
    case 'anrede':
      return /\b(du|dutzen)\b/.test(t) ? 'du' : 'sie';
    case 'tonalitaet':
      return /locker|kollegial|casual/.test(t) ? 'locker' : 'foermlich';
    case 'hat_outlook':
    case 'hat_hubspot':
      return /^(ja|yes|j|klar|genau)/.test(t) ? 'true' : 'false';
    case 'hubspot_token':
      return raw.trim();
    case 'arbeitszeiten':
      return /standard|default|passt/.test(t) ? 'Mo-Fr 09:00-17:00' : raw;
    case 'prioritaeten':
      return /^(nein|no|skip|-)/.test(t) ? '' : raw;
    case 'business_context':
      return /^(nein|no|skip|-)/.test(t) ? '' : raw.trim();
    case 'briefing_uhrzeit':
      return /standard|default|passt/.test(t) ? '07:30' : (raw.match(/\d{1,2}[:.]\d{2}/)?.[0]?.replace('.', ':') || '07:30');
    case 'briefing_inhalt':
      if (/nur kalender|^kalender$/.test(t)) return 'kalender';
      if (/kalender.*mail/.test(t)) return 'kalender_mails';
      return 'alles';
    case 'company_domain':
      return /^(nein|no|skip|-)/.test(t) ? '' : raw.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
    case 'abend_recap_uhrzeit':
      return /standard|default|passt/.test(t) ? '19:00' : (raw.match(/\d{1,2}[:.]\d{2}/)?.[0]?.replace('.', ':') || '19:00');
    case 'name':
    default:
      return raw
        .replace(/^(ich heiße|mein name ist|ich bin|hier ist)\s*/i, '')
        .replace(/[,.]?\s*(sprich|sprech|nenn)\s+mich\s+.*/i, '')
        .replace(/[,.]?\s*(du kannst|bitte)\s+.*(nennen|ansprechen).*/i, '')
        .trim();
  }
}
let updates = {};
if (!isFirstMessage && pendingField && !profile[pendingField]) {
  updates[pendingField] = extractValue(pendingField, userText);
}

// NEU: hubspot_token NIEMALS im Klartext in jonas_profile schreiben (Onboarding
// Profile Update uebernimmt alle updates-Keys 1:1 in eine unverschluesselte
// Postgres-Tabelle). Rohen Token separat rausreichen (fuer verschluesselte
// Ablage in tenant_credentials via "HubSpot Token speichern"), stattdessen
// nur einen Marker in jonas_profile ablegen.
let hubspotToken = '';
if (updates.hubspot_token) {
  hubspotToken = updates.hubspot_token;
  updates.hubspot_token = 'connected';
}

const merged = { ...profile, ...updates };
// hubspot_token nur abfragen, wenn hat_hubspot === 'true' -- sonst wuerde
// jeder Tenant ohne HubSpot trotzdem danach gefragt werden.
const activeFields = FIELDS.filter(f => f.key !== 'hubspot_token' || merged.hat_hubspot === 'true');
const next = activeFields.find(f => !merged[f.key] && merged[f.key] !== '');
let reply, nextPendingField, onboardingComplete = false;

// Microsoft-Login-Link als SEPARATES Feld, HTML-escaped (Parse Mode des
// "Outlook Link senden" Telegram-Node steht explizit auf HTML).
function escapeHtmlUrl(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}
let outlookAuthUrl = '';
if (pendingField === 'hat_outlook' && updates.hat_outlook === 'true') {
  const tenantId = $('Tenant Ergebnis normalisieren').first().json.tenantId;
  const redirectUri = encodeURIComponent('https://n8n.example.com/webhook/oauth-callback');
  const scope = encodeURIComponent('Calendars.ReadWrite Mail.Read Mail.Send offline_access');
  const state = encodeURIComponent(tenantId);
  const authUrl = `https://login.microsoftonline.com/common/oauth2/v2.0/authorize?client_id=YOUR_AZURE_CLIENT_ID&response_type=code&redirect_uri=${redirectUri}&response_mode=query&scope=${scope}&state=${state}`;
  outlookAuthUrl = `Bitte einmal hier klicken und dich mit deinem Microsoft-Konto anmelden, damit ich Zugriff auf deinen Kalender und deine Mails bekomme:\n\n${escapeHtmlUrl(authUrl)}`;
}

// NEU: HubSpot-Setup-Anleitung als SEPARATES Feld, gleiches Muster wie beim
// Outlook-Link -- eigene ungeparste/HTML-Nachricht statt im normalen reply-Text.
let hubspotSetupUrl = '';
if (pendingField === 'hat_hubspot' && updates.hat_hubspot === 'true') {
  const setupUrl = 'https://developers.hubspot.com/docs/apps/legacy-apps/private-apps/overview';
  const scopes = 'crm.objects.contacts.read, crm.objects.contacts.write, crm.objects.deals.read, crm.objects.deals.write, crm.objects.companies.write';
  hubspotSetupUrl = `So verbindest du HubSpot: in deinem HubSpot-Account oben rechts auf das Zahnrad (Settings) -> links "Integrations" -> "Private Apps" -> "Create a private app". Unter "Scopes" mindestens folgende aktivieren: ${scopes}. Danach erstellen und den angezeigten Token (beginnt mit "pat-") hierher kopieren.\n\nAnleitung mit Bildern: ${escapeHtmlUrl(setupUrl)}`;
}

if (isFirstMessage) {
  reply = `Hi! Bevor's losgeht, ein paar kurze Fragen zum Setup. ${FIELDS[0].question}`;
  nextPendingField = FIELDS[0].key;
} else if (next) {
  reply = next.mandatory ? next.question : `Danke! ${next.question}`;
  nextPendingField = next.key;
} else {
  reply = `Perfekt, ${merged.name}, bin startklar. Ab jetzt kannst du mich für Kalender,
Mails und HubSpot nutzen — frag einfach.`;
  nextPendingField = null;
  onboardingComplete = true;
}
return [{ json: { updates, nextPendingField, onboardingComplete, reply: escapeHtml(reply), outlookAuthUrl, hubspotSetupUrl, hubspotToken } }];

