function toBerlinString(isoString) {
  if (!isoString) return null;
  // Outlook liefert UTC ohne 'Z' Suffix oft als naive ISO-String - explizit als UTC parsen
  const utcDate = new Date(isoString.endsWith('Z') ? isoString : isoString + 'Z');
  const berlin = utcDate.toLocaleString('de-DE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit'
  });
  return berlin; // Format: TT.MM.JJJJ, HH:MM
}

const events = $input.first().json.value || [];
const compact = events.map(e => ({
  title: e.subject || '(kein Titel)',
  start: toBerlinString(e.start?.dateTime),
  end: toBerlinString(e.end?.dateTime),
  location: e.location?.displayName || null,
  isAllDay: e.isAllDay || false,
  attendees: (e.attendees || [])
    .map(a => a.emailAddress?.name)
    .filter(Boolean)
}));
return [{
  json: {
    eventCount: compact.length,
    events: compact
  }
}];

