parameters.jsCode:
const items = $input.all();
const leadsRaw = items.map(i => i.json).filter(l => l && l.name);
const paging = $('List Leads Paging bestimmen').first().json;
const searchTerm = paging.search;
const continuing = paging.continuing;
const truncated = leadsRaw.length > 50;
const leads = truncated ? leadsRaw.slice(0, 50) : leadsRaw;
let reply;
if (!leads.length) {
  reply = continuing
    ? 'Das waren schon alle Leads.'
    : (searchTerm ? `Kein Lead zu "${searchTerm}" gefunden.` : 'Du hast noch keine Leads gespeichert.');
} else {
  const header = searchTerm ? `Leads zu "${searchTerm}":` : (continuing ? 'Weitere Leads:' : 'Deine Leads:');
  reply = header + "\n\n" + leads.map(l => {
    let line = `• ${l.name}`;
    if (l.company) line += ` (${l.company})`;
    if (l.contact_info) line += `\n  Kontakt: ${l.contact_info}`;
    if (l.status) line += `\n  Status: ${l.status}`;
    if (l.notes) line += `\n  Notiz: ${l.notes}`;
    return line;
  }).join("\n\n");
  if (truncated) {
    reply += '\n\n(Es gibt noch mehr — sag "weiter" fuer die naechsten 50, oder grenz ein, z.B. "zeig mir Leads von Firma X".)';
  }
}
return [{ json: { reply, hasMore: truncated } }];

const err = $json.error;
