  premeetingsnapshot: 'premeeting_snapshot', 'pre-meeting_snapshot': 'premeeting_snapshot', pre_meeting_snapshot: 'premeeting_snapshot',
  abendrecap: 'abend_recap', 'abend-recap': 'abend_recap'
};
const raw = (ip.feature_name || '').toLowerCase().trim();
const featureName = NORMALIZE[raw] || raw;
if (!ALLOWED.includes(featureName)) {
  return [{ json: { profileKey: null, featureNameRaw: raw } }];
}
return [{ json: {
  profileKey: `${featureName}_aktiv`,
  value: ip.feature_aktiv === true ? 'true' : 'false',
  featureName
} }];

