return [{ json: { search, offset, continuing } }];

const raw = $json.text || '';
let cleanText = raw;
let leadFound = false, leadName = null, leadCompany = null, leadContactInfo = null, leadNotes = null;
const match = raw.match(/LEAD_JSON:\s*(\{[\s\S]*\})\s*$/i);
if (match) {
  cleanText = raw.slice(0, match.index).trim();
  try {
    const parsed = JSON.parse(match[1]);
    leadFound = parsed.found === true;
    leadName = parsed.name || null;
    leadCompany = parsed.company || null;
    leadContactInfo = parsed.contact_info || null;
    leadNotes = parsed.notes || null;
  } catch (e) {
    leadFound = false;
  }
}
if (!leadName) leadFound = false; // ohne Namen kein speicherbarer Lead
return [{ json: { cleanText, leadFound, leadName, leadCompany, leadContactInfo, leadNotes } }];

const cleanText = $('Vision Lead JSON parsen').item.json.cleanText;
