const pendingId = profile.lead_delete_pending_id || null;
const pendingName = profile.lead_delete_pending_name || null;
const requestedAt = profile.lead_delete_requested_at ? new Date(profile.lead_delete_requested_at) : null;
const expired = !requestedAt || (Date.now() - requestedAt.getTime()) > 10 * 60 * 1000;
let mode;
if (ip.delete_confirm === true) {
  mode = (pendingId && !expired) ? 'confirm' : 'expired';
} else if (ip.delete_confirm === false && pendingId) {
  mode = 'cancel';
} else {
  mode = 'search';
}
return [{ json: { mode, pendingId, pendingName, searchTerm: ip.lead_name } }];

const items = $input.all().map(i => i.json).filter(l => l && l.name);
const searchTerm = $('Delete-Lead Router').first().json.searchTerm;
let reply, setPending = false, pendingId = null, pendingName = null;
if (!searchTerm) {
  reply = 'Welchen Lead soll ich loeschen? Bitte Namen nennen.';
} else if (items.length === 0) {
  reply = `Kein Lead zu "${searchTerm}" gefunden.`;
} else if (items.length === 1) {
  setPending = true; pendingId = items[0].id; pendingName = items[0].name;
  reply = `Soll ich den Lead "${items[0].name}"${items[0].company ? ' (' + items[0].company + ')' : ''} wirklich loeschen? Das kann nicht rueckgaengig gemacht werden. Antworte mit "ja" zum Bestaetigen oder "nein" zum Abbrechen.`;
} else {
  reply = `Mehrere Treffer zu "${searchTerm}": ` + items.map(l => l.name).join(', ') + '. Bitte genauer benennen.';
}
return [{ json: { reply, setPending, pendingId, pendingName } }];

const mode = $('Delete-Lead Router').first().json.mode;
